// OPPD-1 PULSAR engine (after Curtis Roads): a train of short pulsarets, one per period of the note.
// FORMANT sets the pulsaret's own frequency (relative to the note), DIVIDE slows the train from tone to rhythm.
// The train is generated by the 'oppd-pulsar' AudioWorklet (js/audio.js).
'use strict';

const PULSAR_WAVES = ['SINE', 'SAW', 'SQUARE', 'NOISE'];
const PULSAR_WINDOWS = ['GAUSS', 'EXPO', 'RECT', 'REVERSE'];
const PULSAR_DIVS = [1, 2, 4, 8, 16, 32, 64, 128];
const pulsarRatio = v => expmap(v, 0.5, 12);

const PULSAR = {
  name: 'PULSAR', poly: 8,
  params: [
    P('formant', 'FORMANT', 0.45, v => 'x' + pulsarRatio(v).toFixed(2)), P('wave', 'WAVE', 0, fList(PULSAR_WAVES), 4),
    P('window', 'WINDOW', 0, fList(PULSAR_WINDOWS), 4), P('divide', 'DIVIDE', 0, v => '/' + PULSAR_DIVS[idxOf(v, PULSAR_DIVS.length)], PULSAR_DIVS.length),
    P('mask', 'MASK', 0, pct), P('jitter', 'JITTER', 0.05, pct), P('fenv', 'F.ENV', 0.2, pct),
    P('swell', 'SWELL', 0.4, v => { const e = swellEnv(v); return fmtSec(e.a) + '/' + fmtSec(e.r); })
  ],
  env: p => swellEnv(p.swell),
  play(rt, part, note, vel, t) {
    const p = part.params, f = mtof(note), env = swellEnv(p.swell);
    const amp = AC.createGain(); amp.gain.value = 0;
    amp.connect(rt.engIn);
    const life = AC.createConstantSource(); life.offset.value = 0; life.connect(amp); life.start(t);
    let node = null;
    if (AU.crusherOk) {
      node = new AudioWorkletNode(AC, 'oppd-pulsar', { numberOfInputs: 0, numberOfOutputs: 1, outputChannelCount: [1] });
      const prm = n => node.parameters.get(n);
      const div = () => PULSAR_DIVS[idxOf(p.divide, PULSAR_DIVS.length)];
      // the shorter the pulsarets are compared to the period, the less energy: compensate the level
      const level = () => { const duty = Math.min(1, 3 / (pulsarRatio(p.formant) * div())); return clamp(0.32 / Math.sqrt(duty), 0.3, 2.6); };
      const out = AC.createGain(); out.gain.value = level();
      node.connect(out); out.connect(amp);
      prm('freq').value = f / div();
      prm('wave').value = idxOf(p.wave, 4); prm('win').value = idxOf(p.window, 4);
      prm('mask').value = p.mask; prm('jitter').value = p.jitter;
      // formant envelope: starts higher and settles on the formant
      const fm = prm('formant'), base = f * pulsarRatio(p.formant);
      fm.setValueAtTime(Math.min(20000, base * (1 + p.fenv * 6)), t);
      fm.setTargetAtTime(base, t, 0.12);
      node._live = id => {
        if (id === 'formant') { fm.cancelScheduledValues(AC.currentTime); tset(fm, f * pulsarRatio(p.formant)); tset(out.gain, level()); }
        else if (id === 'divide') { tset(prm('freq'), f / div(), 0.01); tset(out.gain, level()); }
        else if (id === 'wave') prm('wave').value = idxOf(p.wave, 4);
        else if (id === 'window') prm('win').value = idxOf(p.window, 4);
        else if (id === 'mask') tset(prm('mask'), p.mask);
        else if (id === 'jitter') tset(prm('jitter'), p.jitter);
      };
    }
    const e = envStart(amp.gain, t, env.a, env.d, env.s, 0.95 * vel);
    return mkVoice({
      srcs: [life], amp, e, rel: env.r,
      cleanup: () => { if (node) { node.port.postMessage('stop'); try { node.disconnect(); } catch (er) { /* gone */ } } },
      live(id) { if (node) node._live(id); }
    });
  },
  // three periods of the train: pulsarets (lit) and the silence after them
  view(g, pi, x, y, w, h) {
    const p = PRJ.parts[pi].params, div = PULSAR_DIVS[idxOf(p.divide, PULSAR_DIVS.length)];
    const duty = Math.min(1, 3 / (pulsarRatio(p.formant) * Math.min(div, 4)));
    const wave = idxOf(p.wave, 4), win = idxOf(p.window, 4), cy = y + h * 0.42, hh = h * 0.36;
    g.strokeStyle = C.line; g.lineWidth = 1; g.beginPath(); g.moveTo(x, cy); g.lineTo(x + w, cy); g.stroke();
    const periods = 3, pw = w / periods, t = performance.now() / 1000;
    g.lineWidth = 1.5; g.lineJoin = 'round';
    for (let k = 0; k < periods; k++) {
      // masked pulsars blink out at random (deterministic per period so the drawing does not flicker)
      const masked = p.mask > 0 && (Math.abs(Math.sin((k + Math.floor(t * 2)) * 78.233)) % 1) < p.mask;
      g.strokeStyle = masked ? C.faint : C.accent;
      g.beginPath();
      const len = pw * duty;
      for (let i = 0; i <= len; i++) {
        const u = i / len, c = u * 3;
        let wv;
        if (win === 0) { const q = (u - 0.5) / 0.2; wv = Math.exp(-0.5 * q * q); } else if (win === 1) wv = Math.exp(-6 * u); else if (win === 2) wv = 1; else wv = Math.exp(-6 * (1 - u));
        let s;
        if (wave === 0) s = Math.sin(2 * Math.PI * c); else if (wave === 1) s = 2 * (c - Math.floor(c)) - 1; else if (wave === 2) s = (c - Math.floor(c)) < 0.5 ? 1 : -1; else s = Math.sin(i * 12.9898 + k * 4.1) * 0.9;
        const yy = cy - s * wv * hh, xx = x + k * pw + i;
        if (i) g.lineTo(xx, yy); else g.moveTo(xx, yy);
      }
      g.stroke();
    }
    T(g, div > 4 ? 'RHYTHM /' + div : 'DUTY ' + Math.round(duty * 100) + '%', x + w, y + 6, 7, C.dim, 'right');
    drawScope(g, RT[pi].an, x, y + h - 14, w, 14, KC[3]);
  }
};
ENGINES.pulsar = PULSAR;
ENGINE_LIST.push('pulsar');
